import{_ as t,o as r,c as a,a2 as d}from"./chunks/framework.z3u3TMv0.js";const g=JSON.parse('{"title":"AIHubMix","description":"AIHubMix 免費模型網關：官網入口、*-free 文本與生圖列表、拿 Key 步驟，以及在 MiniTavern 中的填法。","frontmatter":{"title":"AIHubMix","description":"AIHubMix 免費模型網關：官網入口、*-free 文本與生圖列表、拿 Key 步驟，以及在 MiniTavern 中的填法。","head":[["meta",{"name":"keywords","content":"酒館,AI酒館,Ai酒館,迷你酒館,超迷你酒館,MiniTavern,AI夥伴,AI朋友,Ai本地聊天,Silly Tavern,SillyTavern,手機玩Silly Tavern,Silly Tavern手機版,Silly Tavern安卓,Silly Tavern蘋果,AI角色扮演,角色卡,角色扮演,AI聊天,手機AI,離線AI,AI劇情,本地大模型,本地模型,Ollama,LM Studio,世界書,正則,BYOK,使用手冊,教學,character card,AI roleplay,AI companion"}],["meta",{"property":"og:title","content":"AIHubMix · MiniTavern Docs"}],["meta",{"property":"og:description","content":"AIHubMix 免費模型網關：官網入口、*-free 文本與生圖列表、拿 Key 步驟，以及在 MiniTavern 中的填法。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/aihubmix"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/zh-TW/free-cloud/aihubmix"}]]},"headers":[],"relativePath":"zh-TW/free-cloud/aihubmix.md","filePath":"zh-TW/free-cloud/aihubmix.md","lastUpdated":1787224147000}'),o={name:"zh-TW/free-cloud/aihubmix.md"};function i(n,e,l,h,c,s){return r(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="aihubmix" tabindex="-1">AIHubMix <a class="header-anchor" href="#aihubmix" aria-label="Permalink to &quot;AIHubMix&quot;">​</a></h1><p>統一的 <strong>OpenAI 兼容</strong> API 網關，聚合大量模型；其中 <strong>27+ 款帶 <code>-free</code> 後綴的模型</strong>由平臺補貼、可按模型限額免費調用（無需信用卡）。適合一個 Key 對比 GPT / Gemini / GLM / Kimi 等，並試用免費生圖。介紹見官方文 <a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">AIHubMix 上的免費 AI 模型</a>。</p><blockquote><p>額度、模型名單與「新用戶贈送次數」會變，<strong>以 <a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a> 與控制台為準</strong>。</p></blockquote><h2 id="官網與入口" tabindex="-1">官網與入口 <a class="header-anchor" href="#官網與入口" aria-label="Permalink to &quot;官網與入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>資源</th><th>地址</th></tr></thead><tbody><tr><td>官網 / 註冊</td><td><a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a></td></tr><tr><td>免費模型說明</td><td><a href="https://docs.aihubmix.com/cn/blogs/free-ai-models" target="_blank" rel="noreferrer">docs.aihubmix.com/cn/blogs/free-ai-models</a></td></tr><tr><td>模型廣場</td><td><a href="https://aihubmix.com/models" target="_blank" rel="noreferrer">aihubmix.com/models</a></td></tr><tr><td>開發者文檔</td><td><a href="https://docs.aihubmix.com/cn" target="_blank" rel="noreferrer">docs.aihubmix.com/cn</a></td></tr><tr><td>API Base URL</td><td><code>https://aihubmix.com/v1</code></td></tr></tbody></table><h2 id="免費怎麼獲取" tabindex="-1">免費怎麼獲取 <a class="header-anchor" href="#免費怎麼獲取" aria-label="Permalink to &quot;免費怎麼獲取&quot;">​</a></h2><ol><li>打開 <a href="https://aihubmix.com" target="_blank" rel="noreferrer">aihubmix.com</a> 用郵箱或 OAuth 註冊（官方寫明 <strong>無需信用卡</strong>）。</li><li>進入 <strong>API Keys</strong> → 創建 Key（常見格式 <code>sk-…</code>）。</li><li>在模型廣場篩選免費模型，記下 ID（通常以 <code>-free</code> 結尾）。</li><li>在 MiniTavern 用 <strong>自定義 (OpenAI)</strong> / <strong>自定義 (OpenAI Images)</strong> 填 Base URL 與 Key。</li></ol><table tabindex="0"><thead><tr><th>項目</th><th>說明</th></tr></thead><tbody><tr><td>免費方式</td><td>模型 ID 帶 <code>-free</code>；按 <strong>RPM / 每日 token</strong> 等限速，額度按日重置（見各模型頁）</td></tr><tr><td>新用戶</td><td>文宣稱註冊後部分免費模型各贈送有限次數（如 GPT-5.5、GPT-Image-2 等）；充值可解鎖更多 — 以控制台為準</td></tr><tr><td>綁卡</td><td>免費檔通常不需要</td></tr><tr><td>與 OpenRouter 區別</td><td>OpenRouter 免費層偏開源廣度；AIHubMix 強調補貼後的前沿閉源 <code>*-free</code>（如 GPT / Gemini 免費鏡像）</td></tr></tbody></table><h2 id="模型列表" tabindex="-1">模型列表 <a class="header-anchor" href="#模型列表" aria-label="Permalink to &quot;模型列表&quot;">​</a></h2><p>下列摘自官方免費模型文（約 2026-05）；<strong>實際以模型廣場為準</strong>。ID <strong>大小寫敏感</strong>。</p><h3 id="文本-對話-推理" tabindex="-1">文本（對話 / 推理） <a class="header-anchor" href="#文本-對話-推理" aria-label="Permalink to &quot;文本（對話 / 推理）&quot;">​</a></h3><p>走 Chat Completions。MiniTavern 選 <strong>自定義 (OpenAI)</strong>。</p><h4 id="通用對話" tabindex="-1">通用對話 <a class="header-anchor" href="#通用對話" aria-label="Permalink to &quot;通用對話&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>gpt-5.5-free</code></td><td>旗艦對話 / Agent / 代碼（平臺補貼）</td></tr><tr><td><code>gpt-4o-free</code></td><td>多模態視覺</td></tr><tr><td><code>gpt-4.1-free</code></td><td>長上下文（約 1M）</td></tr><tr><td><code>gpt-4.1-mini-free</code> / <code>gpt-4.1-nano-free</code></td><td>速度與成本向</td></tr><tr><td><code>gemini-3-flash-preview-free</code></td><td>超長上下文、多模態</td></tr><tr><td><code>glm-4.7-flash-free</code></td><td>智譜 Flash</td></tr><tr><td><code>mimo-v2-flash-free</code> / <code>ling-2.6-flash-free</code></td><td>低延遲對話</td></tr></tbody></table><h4 id="編碼向" tabindex="-1">編碼向 <a class="header-anchor" href="#編碼向" aria-label="Permalink to &quot;編碼向&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>coding-glm-5.1-free</code></td><td>官方重點推薦的免費編碼檔</td></tr><tr><td><code>coding-glm-5-free</code> / <code>coding-glm-5-turbo-free</code> / <code>coding-glm-4.7-free</code> 等</td><td>GLM 編碼系列</td></tr><tr><td><code>kimi-for-coding-free</code> / <code>k2.6-code-preview-free</code></td><td>Kimi 編碼</td></tr><tr><td><code>coding-minimax-m2-free</code> … <code>coding-minimax-m2.7-free</code></td><td>MiniMax 編碼系列</td></tr><tr><td><code>step-3.5-flash-free</code></td><td>輕量補全</td></tr></tbody></table><h4 id="agent-推理" tabindex="-1">Agent / 推理 <a class="header-anchor" href="#agent-推理" aria-label="Permalink to &quot;Agent / 推理&quot;">​</a></h4><table tabindex="0"><thead><tr><th>模型 ID</th><th>說明</th></tr></thead><tbody><tr><td><code>xiaomi-mimo-v2-pro-free</code></td><td>工具調用 / Agent</td></tr><tr><td><code>xiaomi-mimo-v2.5-free</code></td><td>更長上下文與多工具調用</td></tr></tbody></table><p>角色扮演聊天可先試 <code>gpt-4o-free</code>、<code>gemini-3-flash-preview-free</code> 或 <code>glm-4.7-flash-free</code>；編碼向模型偏代碼補全，未必適合長劇情。</p><h3 id="圖片-文生圖-編輯" tabindex="-1">圖片（文生圖 / 編輯） <a class="header-anchor" href="#圖片-文生圖-編輯" aria-label="Permalink to &quot;圖片（文生圖 / 編輯）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模型 ID</th><th>接口提示</th><th>App</th></tr></thead><tbody><tr><td><code>gpt-image-2-free</code></td><td><code>POST /v1/images/generations</code>（亦支持 edits）</td><td><strong>自定義 (OpenAI Images)</strong></td></tr><tr><td><code>gemini-3.1-flash-image-preview-free</code>（Nano Banana 2）</td><td>官方稱可走 Chat Completions 對話生圖</td><td>生圖連接未必兼容；優先試 Images 端點或改用 <code>gpt-image-2-free</code></td></tr></tbody></table><h3 id="視頻" tabindex="-1">視頻 <a class="header-anchor" href="#視頻" aria-label="Permalink to &quot;視頻&quot;">​</a></h3><p>官方該篇免費清單以 <strong>LLM + 圖像</strong> 為主；視頻能力若有，以模型廣場標註為準。MiniTavern <strong>無內置視頻生成入口</strong>。</p><h2 id="在-minitavern-裡怎麼填" tabindex="-1">在 MiniTavern 裡怎麼填 <a class="header-anchor" href="#在-minitavern-裡怎麼填" aria-label="Permalink to &quot;在 MiniTavern 裡怎麼填&quot;">​</a></h2><p>通用步驟見 <a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a>。</p><h3 id="聊天" tabindex="-1">聊天 <a class="header-anchor" href="#聊天" aria-label="Permalink to &quot;聊天&quot;">​</a></h3><p>路徑：<strong>設置 → 模型 → 模型連接 → 新建</strong></p><ol><li>平臺選 <strong>自定義 (OpenAI)</strong></li><li>Base URL：<code>https://aihubmix.com/v1</code></li><li>粘貼 API Key</li><li>模型 ID 填 <code>gpt-4o-free</code> 或廣場中其它 <code>*-free</code></li><li><strong>測試</strong> → 成功後設為默認</li></ol><h3 id="生圖" tabindex="-1">生圖 <a class="header-anchor" href="#生圖" aria-label="Permalink to &quot;生圖&quot;">​</a></h3><p>路徑：<strong>設置 → 生圖 → 生圖連接</strong></p><ol><li>平臺選 <strong>自定義 (OpenAI Images)</strong></li><li>Base URL 同上</li><li>同一 Key；模型填 <code>gpt-image-2-free</code></li><li>測連後再用於 <code>/imagine</code> 或生圖入口</li></ol><h2 id="相關章節" tabindex="-1">相關章節 <a class="header-anchor" href="#相關章節" aria-label="Permalink to &quot;相關章節&quot;">​</a></h2><ul><li><a href="/ultra_guides/zh-TW/free-cloud/">免費雲端總覽</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/#免費生圖怎麼配">免費生圖</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/opencode-zen">OpenCode Zen</a> — 編碼向精選網關與另一批 Free 文本模型</li><li><a href="/ultra_guides/zh-TW/free-cloud/agnes-ai">Agnes AI</a></li><li><a href="/ultra_guides/zh-TW/free-cloud/openrouter">OpenRouter</a> — 開源 <code>:free</code> 池</li><li><a href="/ultra_guides/zh-TW/manual/model-link">模型連接</a></li></ul>',33)])])}const u=t(o,[["render",i]]);export{g as __pageData,u as default};
